content:
180                          }
   181                  }
   182          }
   183          /*handle uuid*/
   184          memset(uuid, 0, 16);
   185          if (type == GF_ISOM_BOX_TYPE_UUID ) {
   186                  if (gf_bs_available(bs) < 16) {
   187                          return GF_ISOM_INCOMPLETE_FILE;
   188                  }
   189                  gf_bs_read_data(bs, uuid, 16);
   190                  hdr_size += 16;
   191                  uuid_type = gf_isom_solve_uuid_box(uuid);
   192          }
   193
   194          //handle large box
   195          if (size == 1) {
   196                  if (gf_bs_available(bs) < 8) {
   197                          return GF_ISOM_INCOMPLETE_FILE;
   198                  }
   199                  size = gf_bs_read_u64(bs);
   200                  hdr_size += 8;
   201          }
   202          if (!skip_logs)
   203                  GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[iso file] Read Box type %s size "LLD" start "LLD"\n", gf_4cc_to_str(type), size,  start));
   204
   205          if ( size < hdr_size ) {
   206                  GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[iso file] Box size "LLD" less than box header size %d\n", size, hdr_size));
   207                  return GF_ISOM_INVALID_FILE;
   208          }
   209          restore_type = 0;
   210          if ((parent_type==GF_ISOM_BOX_TYPE_STSD) && (type==GF_QT_SUBTYPE_RAW) ) {
   211                  u64 cookie = gf_bs_get_cookie(bs);
   212                  restore_type = type;
   213                  if (cookie & GF_ISOM_BS_COOKIE_VISUAL_TRACK)
