   223                  if (!newBox) return GF_OUT_OF_MEM;
   224                  ((GF_TrackReferenceTypeBox*)newBox)->reference_type = type;
   225          } else if (parent_type && (parent_type == GF_ISOM_BOX_TYPE_IREF)) {
   226                  newBox = gf_isom_box_new(GF_ISOM_BOX_TYPE_REFI);
   227                  if (!newBox) return GF_OUT_OF_MEM;
   228                  ((GF_ItemReferenceTypeBox*)newBox)->reference_type = type;
   229          } else if (parent_type && (parent_type == GF_ISOM_BOX_TYPE_TRGR)) {
   230                  newBox = gf_isom_box_new(GF_ISOM_BOX_TYPE_TRGT);
   231                  if (!newBox) return GF_OUT_OF_MEM;
   232                  ((GF_TrackGroupTypeBox*)newBox)->group_type = type;
   233          } else if (parent_type && (parent_type == GF_ISOM_BOX_TYPE_GRPL)) {
   234                  newBox = gf_isom_box_new(GF_ISOM_BOX_TYPE_GRPT);
   235                  if (!newBox) return GF_OUT_OF_MEM;
   236                  ((GF_EntityToGroupTypeBox*)newBox)->grouping_type = type;
   237          } else {
   238                  //OK, create the box based on the type
   239                  is_special = GF_FALSE;
   240                  newBox = gf_isom_box_new_ex(uuid_type ? uuid_type : type, parent_type, skip_logs, is_root_box);
   241                  if (!newBox) return GF_OUT_OF_MEM;
   242          }
