   244          //OK, init and read this box
   245          if (type==GF_ISOM_BOX_TYPE_UUID && !is_special) {
   246                  memcpy(((GF_UUIDBox *)newBox)->uuid, uuid, 16);
   247                  ((GF_UUIDBox *)newBox)->internal_4cc = uuid_type;
   248          }
