   250          if (!newBox->type) newBox->type = type;
   251          if (restore_type)
   252                  newBox->type = restore_type;
   253
   254          end = gf_bs_available(bs);
   255          if (size - hdr_size > end ) {
   256                  newBox->size = size - hdr_size - end;
   257                  *outBox = newBox;
   258                  return GF_ISOM_INCOMPLETE_FILE;
   259          }
   260
   261          newBox->size = size - hdr_size;
   262
   263          e = gf_isom_full_box_read(newBox, bs);
   264          if (!e) e = gf_isom_box_read(newBox, bs);
   265          if (e) {
   266                  if (gf_opts_get_bool("core", "no-check"))
   267                          e = GF_OK;
   268          }
   269          newBox->size = size;
   270          end = gf_bs_get_position(bs);
   271
   272          if (uncomp_bs) {
   273                  gf_free(uncomp_data);
   274                  gf_bs_del(uncomp_bs);
   275                  if (e) {
   276                          gf_isom_box_del(newBox);
   277                          *outBox = NULL;
   278                          return e;
   279                  }
   280                  //move size to real bitstream offsets for tests below
   281                  size -= 8;
   282                  //remember compressed vs real size info for moof in order to properly recompute data_offset/base_data_offset
   283                  if (type==GF_ISOM_BOX_TYPE_MOOF) {
   284                          ((GF_MovieFragmentBox *)newBox)->compressed_diff = (s32)size - (s32)compressed_size;
   285                  }
   286                  //remember compressed vs real size info for moov in order to properly recompute chunk offset
   287                  else if (type==GF_ISOM_BOX_TYPE_MOOV) {
   288                          ((GF_MovieBox *)newBox)->compressed_diff = (s32)size - (s32)compressed_size;
   289                          ((GF_MovieBox *)newBox)->file_offset = comp_start;
   290                  }
   291                  //remember compressed vs real size info for dump
   292                  else if (type==GF_ISOM_BOX_TYPE_SIDX) {
   293                          ((GF_SegmentIndexBox *)newBox)->compressed_diff = (s32)size - (s32)compressed_size;
   294                  }
   295                  //remember compressed vs real size info for dump
   296                  else if (type==GF_ISOM_BOX_TYPE_SSIX) {
   297                          ((GF_SubsegmentIndexBox *)newBox)->compressed_diff = (s32)size - (s32)compressed_size;
   298                  }
   299                  newBox->internal_flags = GF_ISOM_BOX_COMPRESSED;
   300          }
   301
   302
   303          if (e && (e != GF_ISOM_INCOMPLETE_FILE)) {
   304                  gf_isom_box_del(newBox);
   305                  *outBox = NULL;
   306
   307                  if (!skip_logs) {
   308                          GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Read Box \"%s\" (start "LLU") failed (%s) - skipping\n", gf_4cc_to_str(type), start, gf_error_to_string(e)));
   309                  }
   310                  //we don't try to reparse known boxes that have been failing (too dangerous)
   311                  return e;
   312          }
   313
   314          if (end-start > size) {
   315                  if (!skip_logs) {
   316                          GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] Box \"%s\" size "LLU" (start "LLU") invalid (read "LLU")\n", gf_4cc_to_str(type), size, start, (end-start) ));
   317                  }
   318                  /*let's still try to load the file since no error was notified*/
   319                  gf_bs_seek(bs, start+size);
   320          } else if (end-start < size) {
   321                  u32 to_skip = (u32) (size-(end-start));
   322                  if (!skip_logs) {
   323                          if ((to_skip!=4) || gf_bs_peek_bits(bs, 32, 0)) {
   324                                  GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] Box \"%s\" (start "LLU") has %u extra bytes\n", gf_4cc_to_str(type), start, to_skip));
   325                                  unused_bytes += to_skip;
   326                          }
   327                  }
   328                  gf_bs_skip_bytes(bs, to_skip);
   329          }
   330          *outBox = newBox;
   331
   332          return e;
   333  }
